(function () {
  var G = "#203E38", V = "#155344", CZ = "#78878A", OU = "#A77C20", VM = "#B34E44", TX = "#1C2B2A", K = 0.75;
  var COCAR = "data:image/png;base64,";
  var ST = { dia: ["Em dia", V], atencao: ["Em atenção", OU], atrasado: ["Atrasado", VM] };
  var SG = { dia: "está em dia", atencao: "requer atenção", atrasado: "está atrasado" };
  var PL = { dia: "estão em dia", atencao: "requerem atenção", atrasado: "estão atrasados" };
  var NUM = ["zero", "um", "dois", "três", "quatro"];
  var COM = { "Aldeia Nova": 38, "Boa Esperança": 34, "Água Clara": 30, "São Miguel": 26 };
  var TODAS = "Aldeia Nova, Boa Esperança, Água Clara e São Miguel";
  var FONTES = "Registros comunitários, equipes de campo, sensoriamento remoto e bases institucionais. Consolidação: Ana Costa · Analista FUNAI. Documento demonstrativo com dados fictícios, sem validade oficial.";

  // Dados dos indicadores (iguais aos da tela Indicadores e metas)
  var IND = [
    { id: "cobertura", ord: 2, nome: "Cobertura territorial monitorada", meta: "90%", res: "72%", alc: "80%", st: "atencao", up: "30/06/2026", prio: "Ampliar o monitoramento para os 18 pontos percentuais restantes da meta." },
    { id: "agua", ord: 4, nome: "Pontos de água monitorados", meta: "12 pontos", res: "12 pontos", alc: "100%", st: "dia", up: "30/06/2026", prio: "Manter a análise dos 12 pontos de água." },
    { id: "areas", ord: 3, nome: "Áreas em recuperação", meta: "50 ha", res: "35 ha", alc: "70%", st: "atencao", up: "29/06/2026", prio: "Recuperar os 15 hectares previstos.", foco: "dar continuidade à recuperação de áreas" },
    { id: "rondas", ord: 1, nome: "Rondas de vigilância territorial", meta: "24 rondas", res: "16 rondas", alc: "67%", st: "atrasado", up: "30/06/2026", prio: "Reprogramar as 8 rondas pendentes com a equipe de proteção territorial.", foco: "ampliar as rondas de vigilância" }
  ];
  var ALL = { com: "todas", ids: ["cobertura", "agua", "areas", "rondas"], fmt: "pdf" };
  var HIST = [
    { nome: "Relatório semestral · Indicadores ecológicos", sub: "TI Rio Verde · 4 indicadores · Ana Costa", per: "Jan – jun 2026", data: "30/06/2026", fmt: "pdf", cfg: ALL },
    { nome: "Consolidação mensal · Monitoramento", sub: "TI Rio Verde · 4 indicadores · Ana Costa", per: "Junho 2026", data: "30/06/2026", fmt: "xls", cfg: null },
    { nome: "Relatório de acompanhamento · Maio", sub: "TI Rio Verde · 4 indicadores · Ana Costa", per: "Maio 2026", data: "31/05/2026", fmt: "pdf", cfg: null }
  ];
  var $ = function (s) { return document.querySelector(s); };
  var lista = function (a) { return a.length > 1 ? a.slice(0, -1).join(", ") + " e " + a[a.length - 1] : a[0] || ""; };

  // ---------- Modelo: tudo que o relatório mostra vem daqui ----------
  function modelo(cfg) {
    var todas = cfg.com === "todas";
    var sel = IND.filter(function (i) { return cfg.ids.indexOf(i.id) > -1; });
    var n = sel.length, c = { dia: 0, atencao: 0, atrasado: 0 };
    sel.forEach(function (i) { c[i.st]++; });
    var ord = sel.slice().sort(function (a, b) { return a.ord - b.ord; });
    var partes = [];
    ["dia", "atencao", "atrasado"].forEach(function (k) {
      if (c[k]) partes.push(n === 1 ? SG[k] : NUM[c[k]] + " " + (c[k] === 1 ? SG[k] : PL[k]));
    });
    var foco = ord.filter(function (i) { return i.foco; }).map(function (i) { return i.foco; });
    var p2 = n ? (n > 1 ? "Entre os " + NUM[n] + " indicadores ecológicos selecionados, " : "O indicador ecológico selecionado ") + lista(partes) + "." : "";
    if (foco.length) p2 += (foco.length > 1 ? " As prioridades são " : " A prioridade é ") + lista(foco) + ".";
    var ids = cfg.ids, pr = [];
    ord.forEach(function (i) {
      if (i.id === "agua" && ids.indexOf("areas") > -1) return;
      pr.push(i.id === "areas" && ids.indexOf("agua") > -1 ? "Recuperar os 15 hectares previstos e manter a análise dos 12 pontos de água." : i.prio);
    });
    return {
      sel: sel, n: n, c: c, pr: pr, p2: p2, todas: todas, com: cfg.com,
      sub: "TI Rio Verde · " + (todas ? "Todas as comunidades" : cfg.com),
      comLinha: (todas ? TODAS : cfg.com) + ".",
      p1: todas
        ? "O monitoramento da TI Rio Verde abrangeu 1.280 pessoas em quatro comunidades. No semestre, foram executadas 128 ações, com 84% das demandas atendidas (42 de 50). A cobertura territorial alcançou 72%, frente à meta de 90%."
        : "O monitoramento da comunidade " + cfg.com + ", na TI Rio Verde, registrou " + COM[cfg.com] + " ações executadas no semestre."
    };
  }

  // ---------- Prévia (HTML) ----------
  function htmlRel(m) {
    var kp = [["Indicadores", m.n, ""], ["Em dia", m.c.dia, "dia"], ["Em atenção", m.c.atencao, "atencao"], ["Atrasado", m.c.atrasado, "atrasado"]]
      .map(function (k) { return '<div class="r-k ' + k[2] + '"><b>' + k[1] + "</b><span>" + k[0] + "</span></div>"; }).join("");
    var linhas = m.sel.map(function (i) {
      var s = ST[i.st];
      return '<div class="r-l"><span>' + i.nome + "</span><span>" + i.meta + "</span><span>" + i.res + "</span><span>" + i.alc + '</span><span style="color:' + s[1] + '">' + s[0] + "</span></div>";
    }).join("") || '<div class="r-l"><span style="color:' + CZ + '">Nenhum indicador selecionado.</span></div>';
    return '<div class="r-top"><img src="' + COCAR + '" alt=""><div><b>SISTID</b><span>Sistema de Inteligência Socioterritorial das Terras Indígenas Desintrusadas</span></div><em>MONITORAMENTO E AVALIAÇÃO</em></div>' +
      '<p class="r-et">RELATÓRIO SEMESTRAL · 2026</p><h1>Monitoramento e avaliação territorial.</h1><p class="r-sub">' + m.sub + "</p>" +
      '<div class="r-met"><span>Período: 01/01/2026 a 30/06/2026</span><span>Emitido em: 30/06/2026</span></div><p class="r-com">Comunidades: ' + m.comLinha + "</p>" +
      "<h2>1. Síntese do período</h2><p>" + m.p1 + "</p>" + (m.p2 ? "<p>" + m.p2 + "</p>" : "") + '<div class="r-ks">' + kp + "</div>" +
      "<h2>2. Resultados dos indicadores ecológicos</h2>" +
      '<div class="r-l r-h"><span>Indicador</span><span>Meta</span><span>Resultado</span><span>Alcance¹</span><span>Status</span></div>' + linhas +
      '<p class="r-nota">¹ Alcance = resultado ÷ meta × 100, arredondado. Atualização: 30/06/2026.</p>' +
      "<h2>3. Prioridades para o próximo ciclo</h2><ul>" + m.pr.map(function (t) { return "<li>" + t + "</li>"; }).join("") + "</ul>" +
      '<div class="r-fontes"><b>Fontes e responsabilidade técnica</b><p>' + FONTES + "</p></div>" +
      '<div class="r-rod"><span>SISTID · TI Rio Verde · Relatório nº MON-2026-006</span><span>Página 1 de 1</span></div>';
  }

  // ---------- PDF (texto real, via jsPDF) ----------
  function tx(d, s, x, y, sz, cor, b, al) {
    d.setFont("helvetica", b ? "bold" : "normal"); d.setFontSize(sz * K); d.setTextColor(cor);
    d.text(s, x * K, y * K, { align: al || "left" });
  }
  function rc(d, x, y, w, h, f, l) {
    if (f) d.setFillColor(f);
    if (l) { d.setDrawColor(l); d.setLineWidth(K); }
    d.rect(x * K, y * K, w * K, h * K, f && l ? "FD" : f ? "F" : "S");
  }
  function pdf(m) {
    var d = new window.jspdf.jsPDF({ unit: "pt", format: "a4" }), y;
    d.addImage(COCAR, "PNG", 48 * K, 50 * K, 44 * K, 54 * K);
    tx(d, "SISTID", 108, 88, 26, G, 1);
    tx(d, "Sistema de Inteligência Socioterritorial das Terras Indígenas Desintrusadas", 108, 106, 9, CZ);
    tx(d, "MONITORAMENTO E AVALIAÇÃO", 746, 100, 10, G, 1, "right");
    rc(d, 48, 134, 698, 2, G);
    tx(d, "RELATÓRIO SEMESTRAL · 2026", 48, 172, 10, OU);
    tx(d, "Monitoramento e avaliação territorial.", 48, 214, 30, G);
    tx(d, m.sub, 48, 252, 14, CZ);
    tx(d, "Período: 01/01/2026 a 30/06/2026", 48, 282, 10, TX);
    tx(d, "Emitido em: 30/06/2026", 746, 282, 10, TX, 0, "right");
    tx(d, "Comunidades: " + m.comLinha, 48, 306, 9.5, CZ);
    y = 350; tx(d, "1. Síntese do período", 48, y, 17, G, 1); y += 30;
    [m.p1, m.p2].forEach(function (t) {
      if (!t) return;
      d.setFont("helvetica", "normal"); d.setFontSize(12.5 * K);
      d.splitTextToSize(t, 698 * K).forEach(function (l) { tx(d, l, 48, y, 12.5, TX); y += 20; });
      y += 8;
    });
    y += 4;
    [["Indicadores", m.n, "#F8FAFB"], ["Em dia", m.c.dia, "#E8F2ED"], ["Em atenção", m.c.atencao, "#FCF5DD"], ["Atrasado", m.c.atrasado, "#FBEDEA"]].forEach(function (k, i) {
      var x = 48 + i * 177;
      rc(d, x, y, 166, 76, k[2], "#E4E9EB"); tx(d, String(k[1]), x + 12, y + 36, 24, G, 1); tx(d, k[0], x + 12, y + 58, 10, CZ);
    });
    y += 118;
    tx(d, "2. Resultados dos indicadores ecológicos", 48, y, 17, G, 1); y += 18;
    rc(d, 48, y, 698, 40, "#E8F2ED");
    [["Indicador", 58], ["Meta", 286], ["Resultado", 376], ["Alcance¹", 466], ["Status", 546]].forEach(function (h) { tx(d, h[0], h[1], y + 24, 9, G, 1); });
    y += 40;
    m.sel.forEach(function (i) {
      var s = ST[i.st];
      tx(d, i.nome, 58, y + 25, 9.5, TX); tx(d, i.meta, 286, y + 25, 9.5, TX); tx(d, i.res, 376, y + 25, 9.5, TX);
      tx(d, i.alc, 466, y + 25, 9.5, TX); tx(d, s[0], 546, y + 25, 9.5, s[1]);
      d.setDrawColor("#E4E9EB"); d.line(48 * K, (y + 41) * K, 746 * K, (y + 41) * K); y += 41;
    });
    if (!m.n) { tx(d, "Nenhum indicador selecionado.", 58, y + 25, 9.5, CZ); y += 41; }
    tx(d, "¹ Alcance = resultado ÷ meta × 100, arredondado. Atualização: 30/06/2026.", 48, y + 22, 9, CZ); y += 62;
    tx(d, "3. Prioridades para o próximo ciclo", 48, y, 17, G, 1); y += 28;
    m.pr.forEach(function (t) {
      d.setFillColor(TX); d.circle(54 * K, (y - 3.5) * K, 1.6 * K, "F"); tx(d, t, 64, y, 11.5, TX); y += 22;
    });
    rc(d, 48, 1000, 698, 72, "#F8FAFB");
    tx(d, "Fontes e responsabilidade técnica", 60, 1022, 10, TX);
    d.setFont("helvetica", "normal"); d.setFontSize(9 * K);
    d.splitTextToSize(FONTES, 674 * K).forEach(function (l, i) { tx(d, l, 60, 1040 + i * 13, 9, CZ); });
    d.setDrawColor("#E4E9EB"); d.line(48 * K, 1086 * K, 746 * K, 1086 * K);
    tx(d, "SISTID · TI Rio Verde · Relatório nº MON-2026-006", 48, 1104, 9, CZ);
    tx(d, "Página 1 de 1", 746, 1104, 9, CZ, 0, "right");
    return d.output("blob");
  }

  // ---------- CSV (separador ";" e BOM, para abrir certo no Excel em português) ----------
  function csv(m) {
    var L = [["Relatório", "Monitoramento e avaliação territorial"], ["Território", "TI Rio Verde"], ["Comunidades", m.comLinha.replace(/\.$/, "")], ["Período", "Janeiro a junho de 2026"], [],
      ["Indicador", "Meta", "Resultado", "Alcance", "Status", "Última atualização"]];
    m.sel.forEach(function (i) { L.push([i.nome, i.meta, i.res, i.alc, ST[i.st][0], i.up]); });
    var txt = L.map(function (r) { return r.map(function (c) { return '"' + String(c).replace(/"/g, '""') + '"'; }).join(";"); }).join("\r\n");
    return new Blob(["\ufeff" + txt], { type: "text/csv;charset=utf-8" });
  }

  function arquivo(cfg) { var m = modelo(cfg); return cfg.fmt === "csv" ? csv(m) : pdf(m); }
  function salvar(blob, nome) {
    var a = document.createElement("a");
    a.href = URL.createObjectURL(blob); a.download = nome; document.body.appendChild(a); a.click(); a.remove();
    setTimeout(function () { URL.revokeObjectURL(a.href); }, 5000);
  }
  function baixar(cfg) {
    if (cfg.fmt === "pdf" && !window.jspdf) { toast("Não foi possível carregar o gerador de PDF. Verifique a conexão."); return false; }
    salvar(arquivo(cfg), "relatorio-sistid-mon-2026-006." + cfg.fmt); return true;
  }

  // ---------- Tela ----------
  function lerCfg() {
    return {
      com: $("#f-com").value,
      ids: IND.filter(function (i) { return $("#i-" + i.id).checked; }).map(function (i) { return i.id; }),
      fmt: document.querySelector("input[name=fmt]:checked").value
    };
  }
  function escala() {
    var box = $("#prev-box"), s = box.clientWidth / 794;
    $("#rel").style.transform = "scale(" + s + ")"; box.style.height = 1123 * s + "px";
  }
  function atualizar() {
    var cfg = lerCfg(), m = modelo(cfg);
    $("#rel").innerHTML = htmlRel(m);
    $("#cont").textContent = m.n + (m.n === 1 ? " selecionado" : " selecionados");
    $("#grupo").textContent = m.n === 4 ? "· todos selecionados" : "· " + m.n + " de 4 selecionados";
    $("#resumo").textContent = m.n + (m.n === 1 ? " indicador" : " indicadores") + " · 1 página";
    $("#rod-prev").textContent = cfg.fmt === "csv" ? "Prévia do relatório · o CSV leva só a tabela de dados" : "Visualização para impressão · PDF";
    document.querySelectorAll(".gerar").forEach(function (b) { b.disabled = !m.n; });
    escala();
  }
  function toast(t) {
    var e = $("#toast"); e.querySelector("span").textContent = t; e.hidden = false;
    clearTimeout(window._tt); window._tt = setTimeout(function () { e.hidden = true; }, 4000);
  }
  function hist() {
    $("#hist").innerHTML = HIST.map(function (h, i) {
      return '<tr><td><span class="doc">▤</span><div style="display:inline-block;vertical-align:middle"><b style="font-weight:400">' + h.nome + "</b><small>" + h.sub + "</small></div></td><td>" + h.per + "</td><td>" + h.data +
        '</td><td><span class="fmt-tag">● ' + h.fmt.toUpperCase() + '</span></td><td><button class="lnk" data-i="' + i + '" data-a="ver">Visualizar</button><button class="lnk" data-i="' + i + '" data-a="baixar">⤓ Baixar</button></td></tr>';
    }).join("");
  }

  document.querySelectorAll("#cfg input, #cfg select").forEach(function (e) { e.addEventListener("change", atualizar); });
  document.querySelectorAll(".gerar").forEach(function (b) {
    b.addEventListener("click", function () {
      var cfg = lerCfg();
      if (!baixar(cfg)) return;
      HIST.unshift({ nome: "Relatório semestral · Indicadores ecológicos" + (cfg.com === "todas" ? "" : " · " + cfg.com), sub: "TI Rio Verde · " + cfg.ids.length + " indicadores · Ana Costa", per: "Jan – jun 2026", data: "30/06/2026", fmt: cfg.fmt, cfg: cfg });
      hist(); toast("Relatório gerado e baixado.");
    });
  });
  $("#hist").addEventListener("click", function (e) {
    var b = e.target.closest("button"); if (!b) return;
    var h = HIST[b.dataset.i];
    if (!h.cfg) return toast("Módulo externo não implementado");
    var c = { com: h.cfg.com, ids: h.cfg.ids, fmt: h.fmt };
    if (b.dataset.a === "baixar") return baixar(c) && toast("Arquivo baixado.");
    if (c.fmt === "pdf" && window.jspdf) window.open(URL.createObjectURL(arquivo(c)), "_blank");
    else toast("A visualização está disponível apenas para PDF.");
  });
  $("#toast button").addEventListener("click", function () { $("#toast").hidden = true; });
  window.addEventListener("resize", escala);

  window.SISTID = { modelo: modelo, htmlRel: htmlRel, csv: csv };
  hist(); atualizar();
})();
